import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

good_numbers = set()
N = 30

# Iterate through all distinct triplets a < b < c
for a in range(1, N + 1):
    for b in range(a + 1, N + 1):
        for c in range(b + 1, N + 1):

            # Condition 1: gcd(a, b, c) = 1
            if gcd3(a, b, c) != 1:
                continue

            # Condition 2: For any two distinct elements (x, y), the third (z) must divide xy.
            # Pair {a, b}, third is c: c | ab
            if (a * b) % c != 0:
                continue

            # Pair {a, c}, third is b: b | ac
            if (a * c) % b != 0:
                continue

            # Pair {b, c}, third is a: a | bc
            if (b * c) % a != 0:
                continue

            # It is a good set
            m = a * b * c
            good_numbers.add(m)

# List the resulting good numbers in increasing order
sorted_good_numbers = sorted(list(good_numbers))

print(f"Total number of good sets found: {len(good_numbers)}")
print("List of good numbers (m):")
for i, m in enumerate(sorted_good_numbers):
    print(f"{i+1}: {m}")

